        rows_to_replace: List[int] = []
        new_vecs: List[np.ndarray] = []
        new_metas: List[RagMeta] = []

        for v, m in zip(vectors, metas):
            if m.id in self._id2row:
                rows_to_replace.append(self._id2row[m.id])
                self.meta[self._id2row[m.id]] = m
            else:
