        if rows_to_replace:
            for ridx, v in zip(rows_to_replace, vectors[:len(rows_to_replace)]):
                self.emb[ridx, :] = v


        if new_vecs:
            app = np.vstack(new_vecs)
            self.emb = np.vstack([self.emb, app])
            self.meta.extend(new_metas)

        self._rebuild_id_index()
        self.save()



