def _filter_accept(self, rating: int) -> bool:
    idx = self.filter_combo.currentIndex()
    if idx == 0:
        return True
    elif idx == 1:
        return rating >= 1
    elif idx == 2:
        return rating >= 2
    elif idx == 3:
        return rating >= 3
    elif idx == 4:
        return rating == 0
    return True

