   def _sum_stacks_with_padding(self, stacks: List[np.ndarray]) -> Optional[np.ndarray]:
       if not stacks:
           return None

       max_x = 0
       max_y = 0
       max_f = 0
       for s in stacks:
           if s.ndim != 3:
               continue
           f, x, y = s.shape
           max_f = max(max_f, f)
           max_x = max(max_x, x)
           max_y = max(max_y, y)
       if max_x == 0 or max_y == 0:
           return None
       acc = np.zeros((max_f, max_x, max_y), dtype=np.float32)
       for s in stacks:
           if s.ndim != 3:
               continue
           f, x, y = s.shape
           acc[:f, :x, :y] += s.astype(np.float32, copy=False)
       return acc

